-- Decimal128 and Decimal256 values close to their precision limits must not collapse through Float64.
SELECT quantiles(0, 0.5, 1)(x)
FROM
(
    SELECT toDecimal128(if(number % 2 = 0, '99999999999999999999999999999999999999', '99999999999999999999999999999999999998'), 0) AS x
    FROM numbers(100)
);

SELECT quantiles(0, 0.5, 1)(x)
FROM
(
    SELECT toDecimal256(if(number % 2 = 0, '9999999999999999999999999999999999999999999999999999999999999999999999999999', '9999999999999999999999999999999999999999999999999999999999999999999999999998'), 0) AS x
    FROM numbers(100)
);
